import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, color, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Texture, DoubleSide } = THREE;

  const palette = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Pricing 1', role: 'headline', typography: { fontSize: 39 } },
    ];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const labelText = headlineItem?.text ?? 'Pricing 1';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const group = new Group();
  group.name = 'pricing-card-1-label';

  // ---- Card plane: engineered gradient + subtle grain + thin accent band ----
  const cardWidth = 1.9;
  const cardHeight = 0.56;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.58,
    metalness: 0.38,
    side: DoubleSide,
  });

  const uvNode = uv();
  const topColor = color(palette.ink);
  const bottomColor = color(palette.surface);
  const accentColor = color(palette.accent);

  const grainSeed = uvNode
    .dot(vec2(12.9898, 78.233))
    .sin()
    .mul(43758.5453)
    .fract();

  const rising = smoothstep(0.06, 0.1, uvNode.y);
  const bandFactor = rising.oneMinus();

  let gradientNode = mix(bottomColor, topColor, uvNode.y);
  gradientNode = mix(gradientNode, accentColor, bandFactor.mul(0.82));
  gradientNode = gradientNode.add(vec3(grainSeed).sub(0.5).mul(0.03));

  cardMat.colorNode = gradientNode;
  cardMat.roughnessNode = uniform(0.58).add(grainSeed.mul(0.05));

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  group.add(cardMesh);

  // ---- Headline text: "Pricing 1" ----
  const textObj = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: palette.paper,
    align: 'center',
    maxWidthPx: 480,
  });
  textObj.position.set(0, 0, 0.02);
  group.add(textObj);

  // ---- Decorative orb accent (subtle, corner, <10% of frame) ----
  const decorSize = 0.26;
  const decorGeo = new PlaneGeometry(decorSize, decorSize, 1, 1);
  const decorTex = new Texture();
  const decorMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.4,
    depthWrite: false,
  });
  const decorMesh = new Mesh(decorGeo, decorMat);
  decorMesh.position.set(cardWidth / 2 - 0.2, cardHeight / 2 - 0.16, 0.015);
  decorMesh.visible = false;
  group.add(decorMesh);

  let decorLoadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        decorLoadedTexture = tex;
        decorMat.map = tex;
        decorMat.needsUpdate = true;
        decorMesh.visible = true;
      })
      .catch(() => {
        decorMesh.visible = false;
      });
  }

  // ---- Cinematic primitives (none specified, but honor generically) ----
  const primitiveHandles = [];
  const primitiveSpecs = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];
  for (const prim of primitiveSpecs) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- Weighted, non-perpetual entrance (static composition otherwise) ----
  group.scale.set(0.98, 0.98, 0.98);
  group.position.y += 0; // adapter owns final placement; only relative anim below
  const localY = { v: 0.12 };
  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }).fromTo(
    localY,
    { v: 0.12 },
    {
      v: 0,
      duration: 0.7,
      ease: 'power3.out',
      onUpdate: () => {
        cardMesh.position.y = localY.v;
        textObj.position.y = localY.v;
        decorMesh.position.y = cardHeight / 2 - 0.16 + localY.v;
      },
    },
    0
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      try {
        h.cleanup?.();
      } catch (_) {
        /* noop */
      }
    }
    cardGeo.dispose();
    cardMat.dispose();
    decorGeo.dispose();
    decorMat.dispose();
    if (decorLoadedTexture) decorLoadedTexture.dispose?.();
    decorTex.dispose();
    textObj.traverse?.((child) => {
      child.geometry?.dispose?.();
      if (child.material) {
        const mats = Array.isArray(child.material)
          ? child.material
          : [child.material];
        for (const m of mats) m.dispose?.();
      }
    });
  };

  return group;
}
